    ('R15-V119', 46, 15578, '5e3557a4b5d223e6bbd55aec484a2a8d', 'auswahl', 'abschaetzen', 'a7dd2716e3083cfeeff6e6ccdb2908a8', $rbf${"index": 3}$rbf$::jsonb, 'id.zahlen.hoch_zurueck', $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "0", "text": "12² = 144 ist schon größer als 130", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "1", "text": "11² = 121 ist kleiner als 130, also liegt die Seite über 11 dm", "fehlbild": null, "regel": null}, {"nr": 3, "art": "index", "luecke": null, "wert": "2", "text": "130 durch 2 geteilt, die Wurzel aber nicht halbiert", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R15-V120', 46, 15579, 'd3fd5ef7346bd355de71006a972f3ef7', 'zahl', 'abschaetzen', null, $rbf${"wert": 9.2, "einheit": "m"}$rbf$::jsonb, 'id.zahlen.hoch_zurueck', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "42.5", "text": "die Wurzel wie „geteilt durch 2“ gerechnet", "fehlbild": "fb.hoch_zurueck.wurzel_halbiert", "regel": "id.zahlen.hoch_zurueck"}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "9.5", "text": "die Mitte der beiden Nachbarzahlen als Wurzel genommen", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "9.3", "text": "zu weit gerundet: 9,3² ist 86,49 und liegt weiter von 85 weg", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R15-V121', 46, 15580, '5bb6e0b992095706937dda310953fd73', 'auswahl', 'wurzel_deuten', '23e76c15a9f46a95a1ec7e25b412d7d1', $rbf${"index": 2}$rbf$::jsonb, 'id.zahlen.hoch_zurueck', $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "0", "text": "25 ist eine Quadratzahl, 5 · 5 = 25", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "1", "text": "das hat mit gerade oder ungerade nichts zu tun", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R15-V122', 46, 15581, 'a7b084f1214462547e9d34d1c115d587', 'zahl', 'wurzel_deuten', null, $rbf${"wert": 8}$rbf$::jsonb, 'id.zahlen.hoch_zurueck', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "7", "text": "die Zahl 5 nicht mitgezählt", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "16", "text": "alle ganzen Zahlen von −3 bis 12 gezählt", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "9", "text": "schon bei x = 4 begonnen", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R15-V123', 46, 15582, 'c753ac17d46d18c207aa6a262b352c48', 'auswahl', 'wurzel_deuten', '6cb911a71d07c5765726ebd2cb6fd197', $rbf${"index": 0}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "1", "text": "diese Zeile ist nur die Folge des ersten Fehlers", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "2", "text": "diese Zeile ist nur die Folge des ersten Fehlers", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R15-V124', 46, 15583, '2ab7be6d4ea5f63bc3be9097284a1246', 'zahl', 'wurzel_sache', null, $rbf${"wert": 72, "einheit": "min"}$rbf$::jsonb, 'id.zahlen.hoch_zurueck', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "1.2", "text": "die Zeit in Stunden angegeben, nicht in Minuten", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "18", "text": "nur eine Seite gegangen", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "27", "text": "die Fläche statt des Wegs durch die Geschwindigkeit geteilt", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R15-V125', 46, 15584, '1f45cf20cd6f5d972c6ec26a54248544', 'zahl', 'wurzel_sache', null, $rbf${"wert": 18, "einheit": "m"}$rbf$::jsonb, 'id.zahlen.hoch_zurueck', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "9", "text": "nur sechs Kanten beklebt", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "13.5", "text": "die Kante als Volumen durch 3 berechnet", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "27", "text": "die Kantenlänge quadriert", "fehlbild": null, "regel": null}]$rbf$::jsonb)
  ) x(k, e, r, mt, y, l, ma, o, regel, fb) loop
    select count(*) into n from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if n <> 1 then fehler := fehler || format('%s: %s Übungsaufgaben an Einheit %s, Platz %s', z.k, n, z.e, z.r); continue; end if;
    select * into a from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if md5(coalesce(a.frage->>'text', '')) <> z.mt or a.antworttyp is distinct from z.y or a.variante_gruppe is distinct from z.l
       or (z.ma is not null and md5(coalesce((select string_agg(t.x, E'\n' order by t.o) from jsonb_array_elements_text(a.antworten) with ordinality t(x, o)), '')) <> z.ma) then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s) ist nicht die erwartete (Fragetext/Typ/Lernkarte/Antworten)', z.k, a.id, z.e, z.r); continue; end if;
    -- Lösung samt Einheit und Toleranz wie eingespielt (jsonb-Gleichheit: Zahlen werden als Zahlen verglichen, 12 = 12.0)
    if a.loesung is distinct from z.o then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s): Lösung %s statt %s wie eingespielt', z.k, a.id, z.e, z.r, a.loesung, z.o); continue; end if;
    if a.id = any(v_ids) then fehler := fehler || format('%s: Aufgabe %s doppelt zugeordnet', z.k, a.id); continue; end if;
    v_ids := v_ids || a.id;
    if z.regel is not null then
      insert into schule.aufgabe_regel (aufgabe_id, regel) values (a.id, z.regel) on conflict do nothing;
      get diagnostics c = row_count; n_regel_neu := n_regel_neu + c;
      if (select r.regel from schule.aufgabe_regel r where r.aufgabe_id = a.id) is distinct from z.regel then
        fehler := fehler || format('%s: Aufgabe %s hat schon eine andere Regel', z.k, a.id); end if;
    end if;
    for f in select * from jsonb_array_elements(z.fb) loop
      select * into v_alt from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id and x.nr = (f->>'nr')::smallint;
      if v_alt.nr is null or (v_alt.art, v_alt.luecke, v_alt.wert, v_alt.beschreibung, v_alt.fehlbild, v_alt.regel)
           is distinct from (f->>'art', (f->>'luecke')::smallint, f->>'wert', f->>'text', f->>'fehlbild', f->>'regel') then
        fehler := fehler || format('%s: Fehlbild %s fehlt oder weicht vom Soll ab (nur lesender Vergleich, es wird nichts geschrieben)', z.k, f->>'nr'); continue; end if;
      v := schule.fehlbild_probeantwort(a, f->>'art', (f->>'luecke')::int, f->>'wert');
      b := schule.antwort_bewerten(a, v);
      if not coalesce((b->>'format_ok')::boolean, false) or coalesce((b->>'richtig')::boolean, true) then
        fehler := fehler || format('%s: Fehlbild %s – Antwort %s wird nicht als gültig und falsch bewertet (%s)', z.k, f->>'nr', v, b); continue; end if;
      if schule.fehlbild_finden(a, v) is distinct from (f->>'nr')::smallint then
        fehler := fehler || format('%s: Fehlbild %s wird an der Antwort %s nicht wiedererkannt', z.k, f->>'nr', v); end if;
    end loop;
    if (select count(*) from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id) <> jsonb_array_length(z.fb) then
      fehler := fehler || format('%s: Aufgabe %s hat andere Fehlbilder in der Datenbank als im Paket', z.k, a.id); end if;
  end loop;
  if array_length(fehler, 1) > 0 then raise exception 'RB-S Regelbezug ABBRUCH, alles zurückgerollt (% Befunde): %', array_length(fehler, 1), array_to_string(fehler[1:40], ' | '); end if;
  if n_regel_neu not in (0, 169) then
    raise exception 'RB-S Regelbezug ABBRUCH: % Regeln neu, erlaubt sind nur 0 (Wiederholung) oder 169 (Erstlauf) – Teilvorbestand', n_regel_neu; end if;
  if coalesce(array_length(v_ids, 1), 0) <> 207
     or (select count(*) from schule.aufgabe_regel where aufgabe_id = any(v_ids)) <> 169
     or (select count(*) from schule.aufgabe_fehlbild where aufgabe_id = any(v_ids)) <> 585 then
    raise exception 'RB-S Regelbezug ABBRUCH: Zählung stimmt nicht (Aufgaben %, erwartet 207)', array_length(v_ids, 1); end if;
  raise notice 'RB-S Regelbezug: % Aufgaben, % Regeln neu, % Fehlbilder neu (zweiter Lauf: 0 und 0)', array_length(v_ids, 1), n_regel_neu, n_fb_neu;
end $rbnach$;
do $rnach$
declare v text[] := string_to_array(current_setting('rollend.vorher', true), ' '); n_a bigint; n_f bigint; n_r bigint; d_a bigint; d_f bigint; d_r bigint; b text; wie text;
begin
  if v is null or array_length(v, 1) is distinct from 3 then
    raise exception 'ABBRUCH: die Zählung vorher fehlt (Paket nicht in EINEM Aufruf ausgeführt?)'; end if;
  select count(*) into n_a from schule.aufgabe;
  select count(*) into n_f from schule.aufgabe_fehlbild;
  select count(*) into n_r from schule.aufgabe_regel;
  d_a := n_a - v[1]::bigint; d_f := n_f - v[2]::bigint; d_r := n_r - v[3]::bigint;
  if d_a is distinct from 0 or d_f is distinct from 0 or not coalesce(d_r in (0, 169), false) then
    raise exception 'ABBRUCH, alles zurückgerollt: Differenz Aufgaben % (Soll 0), Fehlbilder % (Soll 0), Regelzuordnungen % (169 beim Erstlauf, 0 bei Wiederholung)', d_a, d_f, d_r; end if;
  wie := case when (v[1], v[2], v[3]) is not distinct from ('32440', '5756', '2004') then 'wie erwartet'
              else 'WEICHT AB von den erwarteten 32440 / 5756 / 2004 (nur die Differenzen sind fest geprüft)' end;
  b := format('Runde 15 Regel-Nachtrag: %s Aufgaben, %s Fehlbilder, %s Regelzuordnungen neu (Soll 0 / 0 / 169 beim Erstlauf, 0 bei Wiederholung); Bestand vorher %s / %s / %s (Aufgaben / Fehlbilder / Regelzuordnungen), %s; nachher %s / %s / %s',
              d_a, d_f, d_r, v[1], v[2], v[3], wie, n_a, n_f, n_r);
  perform set_config('rollend.bericht', b, true);
  raise notice 'BERICHT %', b;
end $rnach$;
select current_setting('rollend.bericht', true) as bericht;
